// Verifies recorded actual moves only; never searches or recommends moves.
function verifyHistory(calls) {
 const b=Object.fromEntries(Object.keys(calls[0].board).map(p=>[p,"."])),moves=[],checks=[],events=[],captured={X:0,O:0};
 function groupAt(p){const seen=new Set([p]),todo=[p],stones=[],libs=new Set(),c=b[p];while(todo.length){const q=todo.pop();stones.push(q);for(const n of neighbors(q)){if(b[n]===".")libs.add(n);else if(b[n]===c&&!seen.has(n)){seen.add(n);todo.push(n);}}}return {stones,libs};}
 function actualMove(color,p){moves.push({number:moves.length+1,color,move:p});if(p==="pass")return;if(b[p]!==".")throw Error("occupied "+p);b[p]=color;const removed=[],checked=new Set();for(const n of neighbors(p)){if(b[n]!=="."&&b[n]!==color&&!checked.has(n)){const g=groupAt(n);g.stones.forEach(s=>checked.add(s));if(g.libs.size===0){g.stones.forEach(s=>{removed.push(s);b[s]=".";});}}}captured[color]+=removed.length;if(groupAt(p).libs.size===0)throw Error("suicide actual "+p);if(removed.length)events.push({number:moves.length,color,move:p,captured:removed.sort()});}
 for(const c of calls){if(c.kind==="play"){actualMove("X",c.move);const reply=c.text.match(/Your opponent played ([A-HJ][1-9])\./);const p=reply?reply[1]:c.text.includes("Your opponent passed.")?"pass":null;if(!p)throw Error("missing reply");actualMove("O",p);}const bad=Object.keys(b).filter(p=>b[p]!==c.board[p]);const count=c.text.match(/Captured by Black: (\d+); by White: (\d+)/);if(bad.length||!count||+count[1]!==captured.X||+count[2]!==captured.O)throw Error("history mismatch "+moves.length);checks.push({afterMove:moves.length,boardMatched:true,capturesMatched:true});}
 const inv=inspect(b),area={X:Object.values(b).filter(x=>x==="X").length,O:Object.values(b).filter(x=>x==="O").length,neutral:0};for(const r of inv.regions){if(r.border.length===1)area[r.border[0]]+=r.points.length;else area.neutral+=r.points.length;}
 return {moves,checks,events,captured,finalInspection:inv,area};
}

